                                  const std::string& op_name) {
CHECK(args.size() == 3) << "The operator " << op_name
                        << " requires 3 arguments (src, indices, tmp), but got " << args.size();

// First arg: src tile (f16, f32, i16, or i32)
auto src_type = As<TileType>(args[0]->GetType());
CHECK(src_type) << "The operator " << op_name << " requires first argument to be a TileType, but got "
                << args[0]->GetType()->TypeName();
CHECK(src_type->dtype_ == DataType::FP16 || src_type->dtype_ == DataType::FP32 ||
      src_type->dtype_ == DataType::INT16 || src_type->dtype_ == DataType::INT32)
    << "The operator " << op_name << " requires src dtype to be FP16, FP32, INT16, or INT32, but got "
    << src_type->dtype_.ToString();

// Second arg: indices tile. i32 is valid with any src; i16 is valid only with a
// 16-bit src (FP16/INT16). The A5 (Ascend950) tgather b16 form pairs a 2-byte
// src with 2-byte indices, whereas a 32-bit src uses the b32 form that reads
// each index as a u32 — so an INT16 index with a 32-bit src is unsafe on every
// target, not merely arch-gated. That universal constraint is checked here in
// the backend-agnostic deducer; A2/A3's i32-only rule is still enforced later
// by the PTOAS verifier (PTO IR manual, tgather index-form checks — A2/A3 vs
// A5).
auto idx_type = As<TileType>(args[1]->GetType());
CHECK(idx_type) << "The operator " << op_name << " requires second argument to be a TileType, but got "
                << args[1]->GetType()->TypeName();
const bool idx_is_i16 = idx_type->dtype_ == DataType::INT16;
const bool src_is_16bit = src_type->dtype_ == DataType::FP16 || src_type->dtype_ == DataType::INT16;
CHECK(idx_type->dtype_ == DataType::INT32 || (idx_is_i16 && src_is_16bit))
    << "The operator " << op_name
    << " requires indices dtype INT32 (any src), or INT16 with a 16-bit src "
       "(FP16/INT16); INT16 indices with a 32-bit src are unsafe (tgather b32 "
       "reads them as u32). Got indices "
    << idx_type->dtype_.ToString() << " with src " << src_type->dtype_.ToString();

// Third arg: tmp workspace tile. A5 (Ascend950) does not read tmp in the
// index form and imposes no tmp dtype/shape relation; A2/A3 requires tmp to
// match the indices element type and valid shape. Deduction is backend-
// agnostic, so only the shared contract (tmp must be a Vec tile operand) is
// checked here — the arch-specific same-type/same-valid-shape rule runs in
// the PTOAS verifier (PTO IR manual, tgather index-form checks — A2/A3).
auto tmp_type = As<TileType>(args[2]->GetType());
CHECK(tmp_type) << "The operator " << op_name << " requires third argument to be a TileType, but got "
                << args[2]->GetType()->TypeName();

// Output: shape from indices tile, dtype from src tile, propagate tile_view
TileView tile_view;
tile_view.valid_shape = idx_type->shape_;
InheritTileViewLayout(tile_view, src_type);
return std::make_shared<TileType>(idx_type->shape_, src_type->dtype_, std::nullopt, tile_view);

// Validate mask_pattern kwarg (values 1-7 per PTOAS MaskPattern enum)
int pattern = -1;
for (const auto& [key, value] : kwargs) {
  if (key == "mask_pattern") {
    pattern = std::any_cast<int>(value);
    break;
  }
}
CHECK(pattern >= 1 && pattern <= 7)
    << "The operator " << op_name << " requires mask_pattern in range [1, 7], but got " << pattern;

// Output shape: mask selects a subset of columns per row, producing a compacted tile.
//   P0101 (1), P1010 (2) — stride 2: each row contributes cols/2 elements
//   P0001 (3)..P1000 (6) — stride 4: each row contributes cols/4 elements
//   P1111 (7)            — no stride: all cols kept
const auto& src_shape = src_type->shape_;
INTERNAL_CHECK_SPAN(src_shape.size() == 2, args[0]->span_)
    << "Internal error: tile.gather_mask requires 2D src shape, got rank " << src_shape.size();

const ExprPtr& col_expr = src_shape[1];
ExprPtr out_col_expr;
if (pattern == 7) {
  out_col_expr = col_expr;  // P1111: all cols
} else {
  int64_t divisor = (pattern <= 2) ? 2 : 4;
  if (auto const_col = As<ConstInt>(col_expr)) {
    int64_t out_cols = const_col->value_ / divisor;
    CHECK(const_col->value_ % divisor == 0)
        << "The operator " << op_name << " with mask_pattern=" << pattern
        << " requires src columns divisible by " << divisor << ", got " << const_col->value_;
    out_col_expr = std::make_shared<ConstInt>(out_cols, DataType::INDEX, Span::unknown());
  } else {
    auto div_expr = std::make_shared<ConstInt>(divisor, DataType::INDEX, Span::unknown());
    out_col_expr = std::make_shared<FloorDiv>(col_expr, div_expr, DataType::INDEX, Span::unknown());
  }
}

std::vector<ExprPtr> out_shape = {src_shape[0], out_col_expr};

};

// ================================================================
// Case 1  rank==2, dim==1 (last dim)
// A5: full-tile gather with flat indices (mirrors tensor.scatter).
// A2A3: legacy per-row loop (column index == flat within rows=1 src).
// ================================================================
if (rank == 2 && norm_dim == 1) {
  int64_t I0 = get_const(index_shape[0], "index.shape[0]");
  int64_t S1 = get_const(input_shape[1], "input.shape[1]");
  int64_t K = get_const(index_shape[1], "index.shape[1]");

  if (IsA5TargetArch()) {
    // INT16 flat-index range guard (same bound as tensor.scatter).
    if (idx_dtype == DataType::INT16) {
      const int64_t kMaxFlat = 32768;
      const int64_t max_rows = S1 == 0 ? kMaxFlat : kMaxFlat / S1;
      CHECK_SPAN(I0 <= max_rows, span)
          << "tensor.gather (A5) with INT16 indices: rows(" << I0 << ") * src_cols(" << S1
          << ") exceeds the INT16 index range (max flat index 32767, rows <= " << max_rows << ").";
    }

    auto zero_ofs = std::make_shared<MakeTuple>(std::vector<ExprPtr>{zero, zero}, span);
    auto inp_sh = MakeShapeTuple({make_idx(I0), make_idx(S1)}, span);
    auto inp_full = emit_load_or_slice(prologue, input, zero_ofs, inp_sh, "gather_inp");
    // Materialize a possibly-strided TileType source (see comment on
    // materialize_src_contig) so the flat-index gather addresses it
    // correctly. TensorType sources are already contiguous (tile.load).
    VarPtr gather_src = inp_full;
    if (As<TileType>(input->GetType())) {
      gather_src = materialize_src_contig(inp_full, I0, S1, input_dtype, "gather_src");
    }
    auto idx_sh = MakeShapeTuple({make_idx(I0), make_idx(K)}, span);
    auto idx_full = emit_load_or_slice(prologue, index, zero_ofs, idx_sh, "gather_idx");

    auto flat_idx = emit_a5_flat_idx(prologue, idx_full, I0, S1, K, "gather");
    auto tmp_sh = MakeShapeTuple({make_idx(I0), make_idx(K)}, span);
    auto tmp = emit("tile.create", {tmp_sh}, tmp_create_kwargs, "gather_tmp");
    auto result = emit("tile.gather", {gather_src, flat_idx, tmp}, {}, "gather");
    return ConversionResult{std::move(prologue), result};
  }

  auto result =
      make_loop(prologue, "gather", index_shape[0], I0, K, input_dtype,
                [&](const VarPtr& lv, const IterArgPtr& /*ia*/, std::vector<StmtPtr>& bs) -> VarPtr {
                  auto row_ofs = std::make_shared<MakeTuple>(std::vector<ExprPtr>{lv, zero}, span);
                  auto inp_sh = MakeShapeTuple({one, make_idx(S1)}, span);
                  auto inp_row = emit_load_or_slice(bs, input, row_ofs, inp_sh, "gather_inp_row");
                  auto idx_sh = MakeShapeTuple({one, make_idx(K)}, span);
                  auto idx_row = emit_load_or_slice(bs, index, row_ofs, idx_sh, "gather_idx_row");
                  return single_row_gather(bs, inp_row, idx_row, K, "gather_row");
                });
  return ConversionResult{std::move(prologue), result};
}

// ================================================================
// Case 2  rank==3, dim==2 (last dim)

__tf__ AICORE void TGather(
    typename TileDataD::TileDType __out__ dst, typename TileDataS0::TileDType __in__ src0,
    typename TileDataS1::TileDType __in__ src1, typename TileDataTmp::TileDType __in__ tmp, unsigned validCol,
    unsigned validRow)
{
    __ubuf__ typename TileDataS0::DType* src0Ptr = (__ubuf__ typename TileDataS0::DType*)__cce_get_tile_ptr(src0);
    __ubuf__ typename TileDataS1::DType* src1Ptr = (__ubuf__ typename TileDataS1::DType*)__cce_get_tile_ptr(src1);
    __ubuf__ typename TileDataD::DType* dstPtr = (__ubuf__ typename TileDataD::DType*)__cce_get_tile_ptr(dst);
    __ubuf__ typename TileDataTmp::DType* tmpPtr = (__ubuf__ typename TileDataTmp::DType*)__cce_get_tile_ptr(tmp);

    unsigned TShape0 = TileDataD::Rows;
    unsigned TShape1 = TileDataD::Cols;
    unsigned idx_stride = TileDataS1::Cols;
    constexpr unsigned blockSizeElem = BLOCK_BYTE_SIZE / sizeof(typename TileDataD::DType);
    constexpr unsigned elementsPerRepeat = REPEAT_BYTE / sizeof(typename TileDataD::DType);
    constexpr unsigned stride = TileDataD::RowStride;
    unsigned numRepeatPerLine = validCol / elementsPerRepeat;
    unsigned numRemainPerLine = validCol % elementsPerRepeat;
    unsigned numLoop = numRepeatPerLine / REPEAT_MAX;
    unsigned remainAfterLoop = numRepeatPerLine % REPEAT_MAX;

    if constexpr (
        std::is_same_v<typename TileDataS0::DType, float> || std::is_same_v<typename TileDataS0::DType, int32_t> ||
        std::is_same_v<typename TileDataS0::DType, uint32_t>) {
        // 64 element per VL
        // counter mode
        set_mask_count();
        for (int i = 0; i < validRow; i++) {
            set_vector_mask(0, validCol);
            vmuls(
                (__ubuf__ int32_t*)(dstPtr + i * TShape1), (__ubuf__ int32_t*)(src1Ptr + i * idx_stride),
                sizeof(typename TileDataD::DType), 1, 1, 1, 8, 8);
            pipe_barrier(PIPE_V);
            vgather(
                (__ubuf__ uint32_t*)(dstPtr + i * TShape1), (__ubuf__ uint32_t*)(dstPtr + i * TShape1),
                (uintptr_t)src0Ptr, 8, 1);
        }

        set_mask_norm();
        set_vector_mask(-1, -1);
    } else {
        // 128 element per VL
        // counter mode
        set_mask_count();
        for (int i = 0; i < validRow; i++) {
            set_vector_mask(0, validCol);
            vmuls(
                (__ubuf__ int32_t*)(tmpPtr + i * TShape1), (__ubuf__ int32_t*)(src1Ptr + i * idx_stride),
                sizeof(typename TileDataD::DType), 1, 1, 1, 8, 8);
            pipe_barrier(PIPE_V);
            vgather(
                (__ubuf__ uint16_t*)(dstPtr + i * TShape1), (__ubuf__ uint32_t*)(tmpPtr + i * TShape1),
                (uintptr_t)src0Ptr, 8, 1);
        }
        set_mask_norm();
        set_vector_mask(-1, -1);
    }
}

template <typename TileDataD, typename TileDataS0, typename TileDataS1, typename TileDataTmp>
PTO_INTERNAL void TGATHER_IMPL(TileDataD& dst, TileDataS0& src0, TileDataS1& src1, TileDataTmp& tmp)
{
    CheckValid<TileDataD, TileDataS0, TileDataS1, TileDataTmp>();
    PTO_ASSERT(src1.GetValidCol() == tmp.GetValidCol(), "Fix: TGATHER expect same cols for indice and tmp buffer.");
    PTO_ASSERT(src1.GetValidRow() == tmp.GetValidRow(), "Fix: TGATHER expect same rows for indice and tmp buffer.");

    unsigned validCol = dst.GetValidCol();
    unsigned validRow = dst.GetValidRow();

    TGather<TileDataD, TileDataS0, TileDataS1, TileDataTmp>(
        dst.data(), src0.data(), src1.data(), tmp.data(), validCol, validRow);
}

template <typename DstTileData, typename SrcTileData, MaskPattern maskPattern, auto gatherType = GatherAxis::GATHER_ROW>
__tf__ AICORE void TGather(
    typename DstTileData::TileDType __out__ dst, typename SrcTileData::TileDType __in__ src, unsigned validRow,
    unsigned validCol)
{
    using T = typename SrcTileData::DType;
    using U = std::conditional_t<sizeof(T) == sizeof(uint32_t), uint32_t, uint16_t>;

    constexpr unsigned srcRepeatStride = SrcTileData::Cols * sizeof(T) / BLOCK_BYTE_SIZE;
    constexpr unsigned dstStride = DstTileData::RowStride;
    constexpr unsigned srcStride = SrcTileData::RowStride;

    __ubuf__ typename DstTileData::DType* dstPtr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(dst);
    __ubuf__ typename SrcTileData::DType* srcPtr = (__ubuf__ typename SrcTileData::DType*)__cce_get_tile_ptr(src);

    set_mask_count();
    set_vector_mask(0, validCol);
    if constexpr (gatherType == GatherAxis::GATHER_COL) {
        uint16_t stride = 0;
        for (int i = 0; i < validRow; i++) {
            stride = GetStrideByMask<maskPattern, srcStride>(i);
            vcopy((__ubuf__ U*)(dstPtr + i * dstStride), (__ubuf__ U*)(srcPtr + stride), 1, 1, 1, 8, 8);
        }
    } else {
        vreducev2(
            reinterpret_cast<__ubuf__ U*>(dstPtr), reinterpret_cast<__ubuf__ U*>(srcPtr),
            reinterpret_cast<__ubuf__ U*>(srcPtr), validRow, 1, maskPattern, srcRepeatStride, 0);
    }
    set_mask_norm();
    set_vector_mask(-1, -1);
}

template <typename DstTileData, typename SrcTileData, MaskPattern maskPattern, auto gatherType = GatherAxis::GATHER_ROW>
PTO_INTERNAL void TGATHER_IMPL(DstTileData& dst, SrcTileData& src)
{
    using T = typename SrcTileData::DType;
    unsigned validRow = src.GetValidRow();
    unsigned validCol = src.GetValidCol();
    static_assert(sizeof(T) == 2 || sizeof(T) == 4, "Fix: TGATHER src element type must be 16 or 32-bit wide");
    static_assert(
        (DstTileData::Loc == TileType::Vec) && (SrcTileData::Loc == TileType::Vec), "Fix: TGATHER expect vec TileType");
    static_assert((DstTileData::isRowMajor && SrcTileData::isRowMajor), "Fix: TGATHER expect row major");
    static_assert(
        (sizeof(typename DstTileData::DType) == sizeof(T)), "Fix: TGATHER expect same type size for dst and src");
    if constexpr (gatherType == GatherAxis::GATHER_ROW) {
        PTO_ASSERT(dst.GetValidCol() == DstTileData::Cols, "Fix: TGATHER expect continuous memory for dst.");
    } else {
        PTO_ASSERT(
            validRow == dst.GetValidRow() * GetTimesByMask<maskPattern>,
            "Fix: TGATHER validRow of dst must be 2 or 4 times that of src.");
    }
    TGather<DstTileData, SrcTileData, maskPattern, gatherType>(dst.data(), src.data(), validRow, validCol);

template <MaskPattern mask, auto ScatterType = ScatterAxis::SCATTER_ROW, typename DstTile, typename SrcTile>
__tf__ PTO_INTERNAL void TScatterMaskImpl(
    typename DstTile::TileDType __out__ dst, typename SrcTile::TileDType __in__ src, unsigned validRow,
    unsigned validCol)
{
    using T = typename DstTile::DType;
    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
    __ubuf__ T* srcPtr = (__ubuf__ T*)__cce_get_tile_ptr(src);
    constexpr unsigned dstStride = DstTile::RowStride;
    constexpr unsigned srcStride = SrcTile::RowStride;

    // Initialize dst UB buffer
    InitUBBuffer<DstTile>(dstPtr);

    if constexpr (ScatterType == ScatterAxis::SCATTER_COL) {
        using copyType = std::conditional_t<sizeof(T) == sizeof(int32_t), __ubuf__ int32_t, __ubuf__ int16_t>;
        uint16_t stride = 0;
        set_mask_count();
        set_vector_mask(0, validCol);
        for (int i = 0; i < validRow; i++) {
            stride = GetStrideByMask<mask, dstStride>(i);
            vcopy((copyType*)(dstPtr + stride), (copyType*)(srcPtr + i * srcStride), 1, 1, 1, 8, 8);
        }
        set_mask_norm();
        set_vector_mask(-1, -1);
    } else {
        int idx = 0;
        for (int i = 0; i < validRow; i++) {
            for (int j = 0; j < validCol; j++) {
                idx = GetIdxByMask<mask, DstTile::RowStride>(i, j);
                dstPtr[idx] = srcPtr[i * SrcTile::Cols + j];
            }
        }
    }
#ifndef __PTO_AUTO__
    PtoSetWaitFlag<PIPE_S, PIPE_V>();
#endif

